<?php require_once 'config/database.php';if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='book'){ $id=filter_input(INPUT_POST,'class_id',FILTER_VALIDATE_INT); if($id){$_SESSION['bookings'][]=$id;} header('Location: cart.php');exit;} $ids=array_unique($_SESSION['bookings']??[]);$items=[];if($ids){$ph=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT c.*,t.trainer_name FROM Classes c LEFT JOIN Trainers t ON c.trainer_id=t.trainer_id WHERE c.class_id IN ($ph)");$s->execute($ids);$items=$s->fetchAll();} ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Bookings | FightClubSA</title><link rel="stylesheet" href="assets/css/style.css"></head><body><header><div class="wrap nav"><a class="logo" href="Index.php">FIGHT<span>CLUBSA</span></a><nav><ul><li><a href="Index.php">Home</a></li><li><a href="catalog.php">Classes</a></li><li><a href="cart.php">My Bookings</a></li><li><a href="login.php">Login</a></li></ul></nav></div></header><main class="section"><div class="wrap"><h2>My Bookings</h2><?php if(!$items):?><div class="notice">You have no bookings yet. <a href="catalog.php"><strong>Browse classes</strong></a>.</div><?php else:?><table class="table"><tr><th>Class</th><th>Trainer</th><th>Date</th><th>Time</th><th>Status</th></tr><?php foreach($items as $i):?><tr><td><?=htmlspecialchars($i['class_name'])?></td><td><?=htmlspecialchars($i['trainer_name'])?></td><td><?=htmlspecialchars($i['schedule_date'])?></td><td><?=substr($i['start_time'],0,5)?></td><td><span class="pill">Confirmed</span></td></tr><?php endforeach;?></table><?php endif;?></div></main><footer>FightClubSA</footer></body></html>
